S=/tmp/claude-1000/-home-rokey-ROKEY-P3-A1/1e88eef7-43a9-4393-aade-53dea58994dd/scratchpad; cd $S && cat > inspect_v3b.py <<'EOF'
import math, sys
from pxr import Usd, UsdGeom
SCENE=sys.argv[1]
def yaw(q):
    w=q.GetReal(); x,y,z=q.GetImaginary(); return math.degrees(math.atan2(2*(w*z+x*y),1-2*(y*y+z*z)))
def f3(v): return "("+", ".join(f"{float(c):.2f}" for c in v)+")"
stage=Usd.Stage.Open(SCENE, Usd.Stage.LoadAll); xc=UsdGeom.XformCache()
bb=UsdGeom.BBoxCache(Usd.TimeCode.Default(),[UsdGeom.Tokens.default_,UsdGeom.Tokens.render],useExtentsHint=True)
def show(p, ind=""):
    m=xc.GetLocalToWorldTransform(p); r=bb.ComputeWorldBound(p).ComputeAlignedRange()
    box="" if r.IsEmpty() else f" bbox={f3(r.GetMin())}..{f3(r.GetMax())}"
    print(f"{ind}{p.GetName()} [{p.GetTypeName()}] T={f3(m.ExtractTranslation())} yaw={yaw(m.ExtractRotationQuat()):.0f}{box}")
sf=stage.GetPrimAtPath("/World/SmartFarm")
for c in sf.GetChildren():
    show(c)
    if c.GetName() in ("Placed","Room"):
        for g in c.GetChildren():
            show(g,"  ")
            if g.GetName()=="Conveyor":
                for s_ in list(g.GetChildren())[:2]: show(s_,"    ")
print("=== LiftRig subtree (depth 3) ===")
lr=stage.GetPrimAtPath("/World/SmartFarm/Placed/LiftRig")
for p in Usd.PrimRange(lr, Usd.TraverseInstanceProxies()):
    d=str(p.GetPath()).count("/")-4
    if d<=3 and (p.GetTypeName() in ("Xform","OmniGraph","PhysicsArticulationRootAPI","") or d<=2):
        show(p,"  "*d)
print("=== OmniGraph nodes with namespace / topic ===")
for p in Usd.PrimRange(stage.GetPseudoRoot(), Usd.TraverseInstanceProxies()):
    if p.GetTypeName()=="OmniGraphNode":
        nt=p.GetAttribute("node:type").Get() or ""
        if any(k in nt for k in ("ROS2","Differential","Clock")):
            ns=p.GetAttribute("inputs:nodeNamespace"); tp=p.GetAttribute("inputs:topicName"); v=p.GetAttribute("inputs:value")
            extra=[]
            for n,a in (("ns",ns),("topic",tp),("value",v)):
                if a and a.HasAuthoredValue(): extra.append(f"{n}={a.Get()!r}")
            print(f"  {p.GetPath()} {nt.split('.')[-1]} {' '.join(extra)}")
EOF
