from pxr import Usd, UsdGeom
import math
st=Usd.Stage.Open('cobot3_ws/isaacpjt/smart_farm/scenes/Collected_smartfarm_v008/Collected_smartfarm_v008.usd')
xc=UsdGeom.XformCache()
def yaw(m):
    q=m.ExtractRotation().GetQuat(); i=q.GetImaginary(); w=q.GetReal()
    return round(math.degrees(math.atan2(2*(w*i[2]+i[0]*i[1]),1-2*(i[1]**2+i[2]**2))),1)
print('up',UsdGeom.GetStageUpAxis(st),'mpu',UsdGeom.GetStageMetersPerUnit(st))
for p in st.Traverse():
    path=p.GetPath().pathString
    if path.count('/')<=4 and p.IsA(UsdGeom.Xformable):
        m=xc.GetLocalToWorldTransform(p); t=m.ExtractTranslation()
        print(path,[round(x,2) for x in t],'yaw',yaw(m))
print('--- graphs / ros nodes')
for p in st.Traverse():
    tn=p.GetTypeName()
    if tn=='OmniGraph': print('GRAPH',p.GetPath())
    if tn=='OmniGraphNode':
        nt=p.GetAttribute('node:type').Get()
        if nt and 'ros2' in nt.lower():
            vals={}
            for a in ('inputs:topicName','inputs:nodeNamespace','inputs:frameId','inputs:chassisFrameId','inputs:odomFrameId','inputs:type'):
                at=p.GetAttribute(a)
                if at and at.Get() not in (None,''): vals[a.split(':')[1]]=at.Get()
            print(' ',p.GetPath().pathString.split('/')[-3:],nt.split('.')[-1],vals)
EOF

